<span class="line"><span style="color:#24292E;">(</span><span style="color:#005CC5;">1.23e+20</span><span style="color:#24292E;">).</span><span style="color:#6F42C1;">toFixed</span><span style="color:#24292E;">(</span><span style="color:#005CC5;">2</span><span style="color:#24292E;">);    </span><span style="color:#6A737D;">// 返回 &quot;123000000000000000000.00&quot;</span></span>
